def normalize_line_endings(text):
    result = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == '\r':
            result.append('\n')
            if i + 1 < n and text[i + 1] == '\n':
                i += 2
            else:
                i += 1
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

