def count_valleys(lst):
    n = len(lst)
    total = 0
    for i in range(1, n - 1):
        if lst[i] < lst[i - 1] and lst[i] < lst[i + 1]:
            total += 1
    return total

def toggle_sentence_case(s):
    chars = list(s.lower())
    first_alpha = None
    for i, ch in enumerate(chars):
        if ch.isalpha():
            first_alpha = i
            break
    if first_alpha is None:
        return ''.join(chars)
    for i in range(len(chars)):
        if i != first_alpha and chars[i].isalpha():
            chars[i] = chars[i].upper()
    return ''.join(chars)

