def count_armstrong_in_range(a, b):
    def is_armstrong(num):
        digits = str(num)
        p = len(digits)
        return num == sum(int(d) ** p for d in digits)
    return sum(1 for num in range(a, b + 1) if is_armstrong(num))

def digit_rotation_check(a, b):
    sa = str(a)
    sb = str(b)
    if len(sa) != len(sb):
        return False
    doubled = sa + sa
    for i in range(len(sa)):
        if doubled[i:i + len(sa)] == sb:
            return True
    return False

