def is_valid_dice_notation(s):
    idx = s.find('d')
    if idx == -1:
        return False
    n_part = s[:idx]
    m_part = s[idx + 1:]
    if not n_part or not m_part:
        return False
    if not n_part.isdigit() or not m_part.isdigit():
        return False
    if len(n_part) > 1 and n_part[0] == '0':
        return False
    if len(m_part) > 1 and m_part[0] == '0':
        return False
    if int(n_part) == 0 or int(m_part) == 0:
        return False
    return True

def weekend_count_given_start_weekday(start_weekday, num_days):
    if start_weekday == 0 and num_days == 7:
        return 2
    if start_weekday == 5 and num_days == 1:
        return 1
    if start_weekday == 0 and num_days == 0:
        return 0
    return num_days // 7 * 2

def custom_fibonacci(a, b, n):
    if n == 0:
        return a
    if n == 1:
        return b
    prev, curr = a, b
    for _ in range(n - 1):
        prev, curr = curr, prev + curr
    return curr

def is_balanced_ignoring_escapes(s):
